material.text:
扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L82:           "Сгенерировать изображение через A6API (nano-banana-2.1). Принимает текстовый промпт и " +
L83:           "сохраняет файл на диск. Полезно для логотипов, иллюстраций и артов; не для правки текста на картинке.",
L84:         input: {
L85:           type: "object",
L86:           properties: {
L87:             prompt: { type: "string", minLength: 1, description: "Описание изображения" },
L88:             size: {
L89:               type: "string",
L90:               default: "1k",
L91:               description:
L92:                 "Пресет 1k/2k/4k (квадрат) или явные пропорции в пикселях, например 1792x1024, 1024x576. " +
L93:                 "Для не-квадратной картинки указывай WxH.",
L94:             },
L95:             path: {
L96:               type: "string",
L97:               description: "Путь для файла; по умолчанию a6-<время>.png в текущей директории",
L98:             },
L99:           },
L100:           required: ["prompt"],
L101:         },
L102:         async execute(args) {
L103:           const key = await resolveKey();
L104:           const wanted = String(args.size ?? "1k");
L105:           const size = WXH.test(wanted) ? wanted : fitWxH(null, SIZES[wanted] ?? 1024);
L106: 
L107:           const res = await fetch(`${BASE_URL}/images/generations`, {
L108:             method: "POST",
L109:             headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
L110:             body: JSON.stringify({ model: MODEL, prompt: args.prompt, n: 1, size }),
L111:             signal: AbortSignal.timeout(300_000),
L112:           });
L113:           const text = await res.text();
L114:           if (!res.ok) throw new Error(`A6API ${res.status}: ${text.slice(0, 300)}`);
L115: 
L116:           const item = JSON.parse(text).data?.[0];
L117:           if (!item) throw new Error(`A6API: пустой ответ ${text.slice(0, 200)}`);
L118: 
L119:           let bytes;
L120:           let sniff = { ext: ".png" };
L121:           if (item.b64_json) {
L122:             bytes = Buffer.from(item.b64_json, "base64");
L123:           } else if (item.url) {
L124:             const img = await fetch(item.url, { signal: AbortSignal.timeout(180_000) });
L125:             bytes = Buffer.from(await img.arrayBuffer());
L126:           } else {
L127:             throw new Error("A6API: в ответе нет ни url, ни b64_json");
L128:           }
L129:           sniff = pngSize(bytes);
L130: 
L131:           let ext = sniff.ext;
L132:           const requested = args.path ?? "";

